INSERT INTO public.questionnaires (id, title, version, description, pass_percent, is_demo, is_active) VALUES ('40000000-0000-4000-8000-000000000101', 'Pesca sportiva con canna', 2, 'Bozza formativa da validare. Bolentino, traina, attrezzature e tutela delle risorse marine.', 80, true, true);
