INSERT INTO public.questionnaires (id, title, version, description, pass_percent, is_demo, is_active) VALUES ('40000000-0000-4000-8000-000000000102', 'Pesca in apnea', 2, 'Bozza formativa da validare. Segnalazione, attrezzatura, comportamento e sicurezza in mare.', 80, true, true);
