INSERT INTO public.questionnaires (id, title, version, description, pass_percent, is_demo, is_active) VALUES ('40000000-0000-4000-8000-000000000103', 'Pesca professionale con reti', 2, 'Bozza formativa da validare. Attrezzi da posta, tracciabilità e protezione della fauna marina.', 80, true, true);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000001301', '40000000-0000-4000-8000-000000000103', 1, 'Da quante "pezze" (pareti di rete) è composta una rete da posta di tipo "Tramaglio"?', '["Una","Due","Tre"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000001302', '40000000-0000-4000-8000-000000000103', 2, 'Come devono essere obbligatoriamente etichettati i segnali (boe) delle reti da posta fisse?', '["Nessun obbligo","Con la matricola e sigla dell''imbarcazione","Con il nome del capitano"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000001303', '40000000-0000-4000-8000-000000000103', 3, 'Come deve essere segnalata una rete da posta fissa calata durante la notte?', '["Con fari rotanti","Con boe radarabili e luci lampeggianti (gialle/bianche)","Nessuna segnalazione"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000001304', '40000000-0000-4000-8000-000000000103', 4, 'Qual è la causa principale della creazione di "Reti Fantasma" (Ghost Fishing)?', '["Ancoraggio errato e forti correnti/maltempo","Reti troppo nuove","Presenza di pesci di grossa taglia"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000001305', '40000000-0000-4000-8000-000000000103', 5, 'Le reti da posta fisse possono essere calate ostruendo il canale di accesso di un porto?', '["Vero","Falso"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000001306', '40000000-0000-4000-8000-000000000103', 6, 'Quale fattore determina principalmente la dimensione minima della maglia autorizzata in una rete da posta?', '["La specie bersaglio (Target)","Il fondale","La lunghezza della barca"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000001307', '40000000-0000-4000-8000-000000000103', 7, 'Cosa deve fare un professionista in caso di cattura accidentale di una Tartaruga Marina (Caretta caretta) viva nella rete?', '["Rimetterla subito in mare anche se comatosa","Issarla a bordo, applicare le procedure di rianimazione e avvisare la Capitaneria","Portarla al mercato"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000001308', '40000000-0000-4000-8000-000000000103', 8, 'In generale, qual è la lunghezza massima consentita per un tramaglio per una piccola imbarcazione costiera?', '["1.000 metri","Fino a 4.000 - 6.000 metri","Nessun limite"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000001309', '40000000-0000-4000-8000-000000000103', 9, 'I pescatori professionali hanno l''obbligo di registrare il pescato su un "Giornale di Pesca" (Logbook)?', '["Vero","Falso"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000001310', '40000000-0000-4000-8000-000000000103', 10, 'Le reti da posta fisse possono essere calate all''interno delle Zone A delle Aree Marine Protette (AMP)?', '["Vero","Falso"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000001311', '40000000-0000-4000-8000-000000000103', 11, 'Quale istituzione è principalmente preposta al controllo delle attività di pesca marittima in Italia?', '["Polizia Municipale","Corpo delle Capitanerie di Porto - Guardia Costiera","Esercito"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000001312', '40000000-0000-4000-8000-000000000103', 12, 'L''utilizzo delle reti da posta derivanti (le cosiddette "spadare") per la pesca dei grandi pelagici è consentito nell''UE?', '["Vero","Falso"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000001313', '40000000-0000-4000-8000-000000000103', 13, 'Che scopo ha il "fermo pesca" biologico obbligatorio?', '["Risparmiare carburante","Tutelare le risorse ittiche nel periodo di massima riproduzione","Evitare il maltempo autunnale"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000001314', '40000000-0000-4000-8000-000000000103', 14, 'Cos''è la rete da "circuizione" (es. cianciolo o lampara)?', '["Una rete trascinata sul fondo","Una rete fissa che aspetta il pesce","Una rete che circonda banchi di pesci pelagici per poi chiudersi sul fondo"]'::jsonb);
INSERT INTO public.questionnaire_questions (id, questionnaire_id, position, prompt, options) VALUES ('50000000-0000-4000-8000-000000001315', '40000000-0000-4000-8000-000000000103', 15, 'Da quale lunghezza "fuori tutto" dell''imbarcazione scatta l''obbligo di avere a bordo il VMS (Vessel Monitoring System) per il tracciamento satellitare?', '["Tutte le barche","Oltre i 12 metri","Oltre i 24 metri"]'::jsonb);
